import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        Scanner in = new Scanner(System.in);
        String nama = in.nextLine();
        File f = new File(nama);
        f.delete();
        f.createNewFile();
        System.out.println("Nama: " + f.getName());
        System.out.println("Ada: " + f.exists());
        System.out.println("Ukuran: " + f.length());
    }
}
